diff --git a/mail/themes/shared/mail/icons.css b/mail/themes/shared/mail/icons.css
index 9d197cb2324..1ec3ad8ea4a 100644
--- a/mail/themes/shared/mail/icons.css
+++ b/mail/themes/shared/mail/icons.css
@@ -11,7 +11,6 @@
   --icon-replies-xs: url("chrome://messenger/skin/icons/xs/replies.svg");

   /* SM - 16x16px icons */
-  --icon-dot-sm: url("chrome://messenger/skin/icons/sm/dot.svg");
   --icon-folder-compact-sm: url("chrome://messenger/skin/icons/sm/folder-compact.svg");
   --icon-sparkle-star-sm: url("chrome://messenger/skin/icons/sm/sparkle-star.svg");

@@ -44,6 +43,7 @@
   --icon-density-relaxed: url("chrome://messenger/skin/icons/new/compact/density-relaxed.svg");
   --icon-display-options: url("chrome://messenger/skin/icons/new/compact/display-options.svg");
   --icon-download: url("chrome://messenger/skin/icons/new/compact/download.svg");
+  --icon-dot: url("chrome://messenger/skin/icons/sm/dot.svg");
   --icon-draft: url("chrome://messenger/skin/icons/new/compact/draft.svg");
   --icon-error-circle: url("chrome://messenger/skin/icons/new/compact/error-circle.svg");
   --icon-export: url("chrome://messenger/skin/icons/new/compact/export.svg");
@@ -269,6 +269,7 @@
 }

 :root[uidensity="compact"] {
+  --icon-dot: var(--icon-dot-xs);
   --spaces-icon-mail: var(--icon-mail);
   --spaces-icon-address-book: var(--icon-address-book);
   --spaces-icon-calendar: var(--icon-calendar);
diff --git a/mail/themes/shared/mail/messageIcons.css b/mail/themes/shared/mail/messageIcons.css
index 18b23b8b750..7f027de0c53 100644
--- a/mail/themes/shared/mail/messageIcons.css
+++ b/mail/themes/shared/mail/messageIcons.css
@@ -121,7 +121,7 @@ treechildren::-moz-tree-image(threadCol, selected, focus) {
 /* ..... read column ..... */

 treechildren::-moz-tree-image(unreadButtonColHeader) {
-  list-style-image: var(--icon-dot-xs);
+  list-style-image: var(--icon-dot);
   -moz-context-properties: stroke, fill, fill-opacity;
   fill: color-mix(in srgb, currentColor 20%, transparent);
   stroke: currentColor;
diff --git a/mail/themes/shared/mail/threadCard.css b/mail/themes/shared/mail/threadCard.css
index 3312b35edc0..d303146d94a 100644
--- a/mail/themes/shared/mail/threadCard.css
+++ b/mail/themes/shared/mail/threadCard.css
@@ -8,9 +8,8 @@
   --thread-card-content-gap: 3px;
   --thread-indicator-content-padding: 2px 3px;
   --thread-line-height: 100%;
-  --read-status-unread: var(--icon-dot-sm);
   --read-status-new: var(--icon-sparkle-star-sm);
-  --read-status-icon: var(--read-status-unread);
+  --read-status-icon: var(--icon-dot);
   --read-status-size: 16px;
   --indicator-gap: 3px;
   --inset-inline-start: 0;
@@ -21,7 +20,6 @@
     --thread-card-content-block: 1px;
     --thread-card-content-gap: 1px;
     --thread-indicator-content-padding: 1px 3px;
-    --read-status-unread: var(--icon-dot-xs);
     --read-status-new: var(--icon-sparkle-star-xs);
     --read-status-size: 12px;
     --indicator-gap: 2px;
diff --git a/mail/themes/shared/mail/threadPane.css b/mail/themes/shared/mail/threadPane.css
index a6f94614b04..f1c88cd0e6a 100644
--- a/mail/themes/shared/mail/threadPane.css
+++ b/mail/themes/shared/mail/threadPane.css
@@ -338,7 +338,7 @@ tr:not([data-properties~="attach"]) :is(.attachmentcol-column img, .attachment-i
   }

   & img {
-    content: var(--icon-dot-xs);
